head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnDisplayFormatter]<br/>Body Column 정보를 사용하여 특정 Column 의 displayFormatter 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 displayFormatter 속성을 설정하려는 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



// displayFormatter 사용자 정의 함수 : Cell 의 실제 데이터가 파라미터로 전달되고, 반환값이 Cell 에 표시됨
//  - data + ' 원' 으로 변환하여 표시 (모든 Row 에 적용됨)
scwin.fmtWon = function (data) {
    return data + " 원";
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Column(text) 구성. setColumnDisplayFormatter 를 Column ID 로 호출.
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column - ctext / cqty. 사용자 정의 함수 scwin.fmtWon(data) 은 (data + 원) 을 반환. setColumnDisplayFormatter 의 columnInfo 파라미터를 (인덱스가 아닌) Column ID 문자열로 호출.\n[절차] columnInfo(Column ID) 선택 후 (setColumnDisplayFormatter 실행) 클릭 -> 선택한 Column 의 ID 와 사용자 함수 이름으로 setColumnDisplayFormatter 호출.\n[확인] Column ID 로 호출되어 해당 Column 의 모든 Row 셀에 사용자 함수 반환값(데이터 원) 이 표시됨. 반환영역에 적용 후 셀 표시값 출력."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cqty" name="cqty" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "ctext": "1250",  "cqty": "10" },
        { "ctext": "30000", "cqty": "25" },
        { "ctext": "475",   "cqty": "7"  }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 2컬럼 + gBody. body 컬럼 id 는 dataList 컬럼 id 와 동일해야 바인딩)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:400px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnDisplayFormatter 테스트 그리드 (Column ID 호출)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol1" value="금액(ctext)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="수량(cqty)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" inputType="text" dataType="text" id="ctext" dataList="ctext"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="text" id="cqty" dataList="cqty"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [실행] setColumnDisplayFormatter : columnInfo 파라미터에 (인덱스가 아닌) Column ID 문자열을 전달하여 displayFormatter 를 설정한다.
//  - 사용자 정의 함수 scwin.fmtWon 의 반환값(데이터 + ' 원') 이 해당 Column 의 모든 Row 셀에 적용됨
//  - 적용 후 해당 Column 의 모든 Row 셀 표시값을 수집하여 사용자 함수 반환값이 적용된 결과를 확인
scwin.btn_setColumnDisplayFormatter_onclick = function () {
    // columnInfo 파라미터 : Column ID 문자열
    let colID = par_columnInfo.getValue();

    // columnInfo 파라미터에 Column ID 문자열을 전달하여 호출 (formatter : 사용자 함수 이름)
    target1.setColumnDisplayFormatter(colID, "scwin.fmtWon");

    // 적용 후 해당 Column 의 모든 Row 화면 표시값 수집 (사용자 함수 반환값이 셀에 표시됨)
    let colIndex = target1.getColumnIndex(colID);
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + colIndex + "']");
        arr.push(td ? td.textContent.trim() : '');
    }

    wf_body_bottom.getObj("scwin").setReturnValue("setColumnDisplayFormatter('" + colID + "', 'scwin.fmtWon') -> '" + colID + "' Column 셀 표시값 : " + arr.join(', '));
}
